SHARES_PATH = "/presentation/shares"
WRITE_TOKEN_HEADER = "x-dfo-write-token"


def share(
    transport: Transport,
    cards: object,
    *,
    latest: object,
    replace: object = None,
    write_token: object = None,
) -> Share:
    """Publish `cards` as a new share, or give the live share `replace` names
    these cards under its URLs.

    Raises:
        InvalidRequestError: `cards` is not a Card or a non-empty list of them,
            `latest` is not a bool, `replace` is given with `latest=False`, or
            `replace` or `write_token` is malformed (`invalid_argument`), and
            no request is sent; or DFO refused the token
            (`write_token_required`) or the share (`share_not_replaceable`).
        PermissionDeniedError: The token is not the share's
            (`write_token_invalid`).
        QuotaExceededError: The daily share allowance is spent
            (`allowance_exhausted`).
    """
    shown = _shown_cards(cards, transport.caller)
    if not isinstance(latest, bool):
        raise client_error(
            INVALID_ARGUMENT,
            "latest is True for a share that follows new data or False for a "
            f"snapshot that keeps today's versions, not {latest!r}",
        )
    if replace is None:
        if write_token is not None:
            raise client_error(
                INVALID_ARGUMENT,
                "write_token goes with replace=, the share whose cards it replaces",
            )
        token = "shw_" + secrets.token_urlsafe(16)
        response = transport.request(
            "POST",
            SHARES_PATH,
            json={"cards": shown, "latest": latest, "write_token": token},
        )
        return _share(response, f"POST {SHARES_PATH}", token)
    share_id = share_id_of(replace, transport.caller)
    if not latest:
        raise client_error(
            INVALID_ARGUMENT,
            "replace= gives a live share new cards, so it takes latest=True; "
            f"{transport.caller}.snapshot(share) fixes a live share as it shows now",
        )
    token = write_token_of(replace, write_token)
    path = f"{SHARES_PATH}/{share_id}"
    response = _change(transport, "PUT", path, share_id, token, json={"cards": shown})
    return _share(response, f"PUT {path}", token)


def snapshot(
    transport: Transport, target: object, *, write_token: object = None
) -> Share:
    """Fix the live share `target` names as a snapshot, under the same URLs.

    Raises:
        InvalidRequestError: `target` or `write_token` is malformed
            (`invalid_argument`), and no request is sent; or no token was given
            (`write_token_required`).
        PermissionDeniedError: The token is not the share's
            (`write_token_invalid`).
    """
    share_id = share_id_of(target, transport.caller)
    token = write_token_of(target, write_token)
    path = f"{SHARES_PATH}/{share_id}/snapshot"
    response = _change(transport, "POST", path, share_id, token)
    return _share(response, f"POST {path}", token)


def unshare(
    transport: Transport, target: object, *, write_token: object = None
) -> None:
    """Take the share `target` names down. A token holder who takes it down
    again succeeds, so a retry is safe.

    Raises:
        InvalidRequestError: `target` or `write_token` is malformed
            (`invalid_argument`), and no request is sent; or no token was given
            (`write_token_required`).
        PermissionDeniedError: The token is not the share's
            (`write_token_invalid`).
        NotFoundError: No share has that id (`not_found`).
    """
    share_id = share_id_of(target, transport.caller)
    token = write_token_of(target, write_token)
    _change(transport, "DELETE", f"{SHARES_PATH}/{share_id}", share_id, token)


def history(
    transport: Transport, target: object, *, deadline: float | None = None
) -> tuple[Served, ...]:
    """Every frame the share `target` names served, newest first, read by the
    clock reading `deadline` when one is given. A long history is read page by
    page.

    Raises:
        InvalidRequestError: `target` is malformed (`invalid_argument`), and no
            request is sent.
        NotFoundError: No share has that id, or it was taken down (`not_found`).
        ContractError: A page repeats a cursor, or is empty and names a next
            page (`contract_violation`).
    """
    return tuple(
        [
            served
            for page in _history_pages(transport, target, deadline)
            for served in page
        ]
    )


def _history_pages(
    transport: Transport, target: object, deadline: float | None
) -> Iterator[tuple[Served, ...]]:
    """The pages of the share's history, newest first, read one request at a
    time, so a caller that has what it needs stops asking."""
    path = f"{SHARES_PATH}/{share_id_of(target, transport.caller)}/history"
    read: set[str] = set()
    cursor: str | None = None
    while True:
        params = None if cursor is None else {"before": cursor}
        response = transport.request("GET", path, params=params, deadline=deadline)
        reply = response_json(response)
