def shown_frame(
    transport: Transport,
    target: object,
    *,
    slot: object = None,
    as_of: object = None,
    deadline: float | None = None,
) -> ShownFrame:
    """The frame slot `slot` of the share `target` names shows now, or showed at
    `as_of`, with every read done by the clock reading `deadline`.

    Raises:
        InvalidRequestError: `target`, `slot` or `as_of` is malformed, or slot
            is 0 (`invalid_argument`), and no request is sent; `slot` is None
            for a share of several slots, or past its last; `as_of` is before
            the slot first served data; or the slot shows a card that draws no
            data, such as a note.
        NotFoundError: No share has that id, or the slot is empty, or with
            `as_of` it showed no card at that moment (`not_found`).
    """
    share_id = share_id_of(target, transport.caller)
    check_slot(slot)
    asked = None if as_of is None else as_of_moment(as_of)
    path = f"{SHARES_PATH}/{share_id}"
    response = transport.request("GET", path, deadline=deadline)
    reply = response_json(response)
    with describing(trace_id_of(response, reply)):
        count, live = read_slot_count(reply, route=f"GET {path}")
    number = chosen_slot(slot if isinstance(slot, int) else None, count, share_id)
    if asked is None:
        path = f"{SHARES_PATH}/{share_id}/slots/{number}"
        response = transport.request("GET", path, deadline=deadline)
        reply = response_json(response)
        with describing(trace_id_of(response, reply)):
            frame, title = read_shown_card(reply, route=f"GET {path}")
        if frame is None:
            raise client_error(
                INVALID_ARGUMENT,
                f"Slot {number} of share {share_id} shows a card that draws no "
                "data, such as a note, so it has no rows to fetch",
            )
        today = datetime.now(UTC).date()
        return ShownFrame(share_id, number, title, *frame, today)
    moment, day = asked
    # The latest entry at or before the moment wins, compared to the
    # millisecond as the TypeScript client compares them. Of entries served in
    # one millisecond the first the history lists wins, since DFO lists a slot's
    # entries of one moment newest first. Pages are newest first too, so the
    # first page with an entry at or before the moment holds the winner.
    entry = None
    for page in _history_pages(transport, target, deadline):
        entry = max(
            (
                served
                for served in page
                if served.slot == number
                and to_millisecond(served.first_served) <= moment
            ),
            key=lambda served: to_millisecond(served.first_served),
            default=None,
        )
        if entry is not None:
            break
    if entry is None:
        raise client_error(
            INVALID_ARGUMENT,
            f"Slot {number} of share {share_id} served no data on or before "
            f"{day.isoformat()}; {transport.caller}.history(share) lists what "
            "each slot showed and when",
        )
    if (
        entry.card_id is None
        or entry.card_revision is None
        or entry.spec_id is None
        or entry.content_version is None
    ):
        raise NotFoundError(
            f"Slot {number} of share {share_id} showed no card on "
            f"{day.isoformat()}; {transport.caller}.history(share) lists what "
            "each slot showed and when",
            code="not_found",
        )
    title = _card_title(
        transport, entry.card_id, entry.card_revision, deadline=deadline
    )
    return ShownFrame(
        share_id, number, title, entry.spec_id, entry.content_version, day, live
    )


def _card_title(
    transport: Transport, card_id: str, revision: int, *, deadline: float | None
) -> str | None:
    """The title a card revision shows, from its read."""
    path = f"/presentation/components/{card_id}"
    response = transport.request(
        "GET", path, params={"revision": revision}, deadline=deadline
    )
    return card_title(response_json(response))


def _shown_cards(cards: object, caller: str) -> list[dict[str, object]]:
    """The cards a share shows, slot 1 first, as the request names them."""
    if isinstance(cards, Card):
        cards = [cards]
    if (
        isinstance(cards, str)
        or not isinstance(cards, Sequence)
        or not cards
        or not all(isinstance(card, Card) for card in cards)
    ):
        raise client_error(
            INVALID_ARGUMENT,
            "A share shows a Card or a list of Cards, such as "
            f"{caller}.cards.line(data), not {type(cards).__name__}",
        )
    return [
        {"component_id": card.id, "revision": card.revision}
        for card in cards
        if isinstance(card, Card)
    ]


def _change(
    transport: Transport,
    method: str,
    path: str,
    share_id: str,
    token: str | None,
    *,
    json: object = None,
) -> httpx2.Response:
    """Send a change of a share with its write token.

    Raises:
        InvalidRequestError: No token was given (`write_token_required`); the
            message names the argument that takes it.
    """
    headers = None if token is None else {WRITE_TOKEN_HEADER: token}
    try:
        return transport.request(method, path, json=json, headers=headers)
    except DfoError as error:
        if error.code != "write_token_required":
            raise
        caller = transport.caller
        raise recast(
            error,
            type(error),
            message=(
                f"Changing share {share_id} needs its write token: pass "
                f"write_token='shw_…', the token on the Share {caller}.share "
                "returned, which DFO gives only when the share is made"
            ),
        ) from error


def _share(response: httpx2.Response, route: str, token: str | None) -> Share:
    reply = response_json(response)
    with describing(trace_id_of(response, reply)):
        return read_share(reply, route=route, write_token=token)
